using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class ConfigureExplorationWorld {
 const string Folder="Assets/Game/Generated/ExplorationWorld/";
 static Material Ground(string name,string maps,string color,string normal,string rough,float scale){
 var mat=new Material(Shader.Find("Game/Living Forest")){name=name,enableInstancing=true};mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(maps+color));if(normal!=null){var path=maps+normal;var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer!=null&&importer.textureType!=TextureImporterType.NormalMap){importer.textureType=TextureImporterType.NormalMap;importer.SaveAndReimport();}mat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));mat.SetFloat("_BumpScale",.45f);}if(rough!=null){mat.SetTexture("_RoughnessMap",AssetDatabase.LoadAssetAtPath<Texture2D>(maps+rough));mat.SetFloat("_UseRoughness",1);}mat.SetFloat("_SnowAmount",0);mat.SetFloat("_UseWorldTextures",1);mat.SetFloat("_WorldTextureScale",scale);mat.SetFloat("_Cull",2);AssetDatabase.CreateAsset(mat,Folder+name+".mat");return mat;
 }
 public static object Main(){
 var scene=SceneManager.GetActiveScene();if(Application.isPlaying||scene.isDirty||scene.path!="Assets/MountainDrive/MountainPass.unity")throw new Exception("Expected saved MountainPass in Edit Mode");if(GameObject.Find("Exploration world - 10 x 10 km")!=null)throw new Exception("Already configured");
 const string backup="Assets/Game/Scenes/BeforeExplorationWorld.unity";if(!File.Exists(backup))EditorSceneManager.SaveScene(scene,backup,true);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var palette=ScriptableObject.CreateInstance<ExplorationPalette>();palette.name="Exploration world material and model palette";
 palette.forest=Ground("Forest floor PBR","Assets/Game/Art/ForestEnhancement/forest_ground_04/","forest_ground_04_diff_2k.jpg","forest_ground_04_nor_gl_2k.jpg","forest_ground_04_rough_2k.jpg",.35f);
 palette.road=Ground("Dirt trail PBR","Assets/Game/Art/RoadScans/bicycle-trail-road-tile-texture/","BicycleTrailRoad_basecolor.jpg",null,"BicycleTrailRoad_roughness.jpg",.4f);
 palette.road.SetFloat("_UseWorldTextures",0);
 palette.mud=Ground("Deep wet mud PBR","Assets/Game/Art/Puddles/","brown_mud_03_diff_2k.jpg","brown_mud_03_nor_gl_2k.jpg","brown_mud_03_rough_2k.jpg",.65f);
 palette.shore=Ground("Lake stone shore PBR","Assets/Game/Art/ForestEnhancement/river_small_rocks/","river_small_rocks_diff_2k.jpg","river_small_rocks_nor_gl_2k.jpg","river_small_rocks_rough_2k.jpg",.6f);
 palette.water=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/Game/Generated/StormRoad/Rain road water.mat")){name="Lake and puddle ripples"};palette.water.SetFloat("_NormalStrength",.12f);AssetDatabase.CreateAsset(palette.water,Folder+"Lake and puddle ripples.mat");
 palette.lakeWater=new Material(palette.water){name="Deep forest lake water"};palette.lakeWater.SetColor("_BaseColor",new Color(.025f,.09f,.105f,.9f));palette.lakeWater.shader=Shader.Find("Game/Exploration Lake Water");palette.lakeWater.SetColor("_BaseColor",new Color(.025f,.1f,.13f,.94f));palette.lakeWater.SetFloat("_NormalStrength",.3f);AssetDatabase.CreateAsset(palette.lakeWater,Folder+"Deep forest lake water.mat");
 palette.roadSoil=AssetDatabase.LoadAssetAtPath<SoftGroundProfile>("Assets/Game/Generated/WindingRoad/Packed road soil.asset");palette.puddleDisk=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Game/Generated/StormRoad/Puddle disk.asset");
 var trees=new List<GameObject>();var materialMap=new Dictionary<Material,Material>();string source="Assets/Game/Generated/LowPolyForest/";
 var sources=AssetDatabase.FindAssets("t:Prefab",new[]{source.TrimEnd('/')}).Select(g=>AssetDatabase.GUIDToAssetPath(g)).Where(p=>!p.Contains("/Animated ")).ToArray();
 foreach(string path in sources){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(prefab.GetComponent<CapsuleCollider>()==null)continue;var instance=UnityEngine.Object.Instantiate(prefab);foreach(var renderer in instance.GetComponentsInChildren<Renderer>()){
 var old=renderer.sharedMaterial;if(!materialMap.TryGetValue(old,out var material)){material=new Material(old){name="Wind "+old.name,enableInstancing=true};var texture=old.GetTexture("_BaseMap");float clip=old.GetFloat("_AlphaClip"),cut=old.GetFloat("_Cutoff"),cull=old.GetFloat("_Cull");material.shader=Shader.Find("Game/Living Forest");material.SetTexture("_BaseMap",texture);material.SetFloat("_AlphaClip",clip);material.SetFloat("_Cutoff",cut);material.SetFloat("_Cull",cull);material.SetFloat("_SnowAmount",0);material.SetFloat("_TreeSway",.055f);material.SetFloat("_LeafFlutter",old.name.StartsWith("Trunk")?0:.045f);material.SetFloat("_LocalWindAnchor",1);AssetDatabase.CreateAsset(material,Folder+material.name+".mat");materialMap.Add(old,material);}renderer.sharedMaterial=material;}
 trees.Add(PrefabUtility.SaveAsPrefabAsset(instance,Folder+"Tree "+prefab.name+".prefab"));UnityEngine.Object.DestroyImmediate(instance);}
 palette.trees=trees.ToArray();palette.rocks=sources.Select(p=>AssetDatabase.LoadAssetAtPath<GameObject>(p)).Where(p=>p.name.StartsWith("Rocks")).ToArray();palette.fallenTrees=sources.Select(p=>AssetDatabase.LoadAssetAtPath<GameObject>(p)).Where(p=>p.name.StartsWith("Detailed")).ToArray();AssetDatabase.CreateAsset(palette,Folder+"World palette.asset");
 var go=new GameObject("Exploration world - 10 x 10 km");var world=go.AddComponent<ExplorationWorld>();world.palette=palette;world.vehicle=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>().transform;world.weather=UnityEngine.Object.FindAnyObjectByType<ForestDayNightWeather>();world.wind=go.AddComponent<ForestWind>();world.wind.strength=.65f;
 string[] replaced={"Ground - square 100 x 100 m","Winding road - persistent wheel ruts","Soft forest floor - wheel ruts","Low poly forest - planted territory","Random road blockages","Rain puddles - road basins"};world.replacedRoots=replaced.Select(n=>GameObject.Find(n)).ToArray();if(world.replacedRoots.Any(r=>r==null))throw new Exception("Missing old environment root");var audio=go.AddComponent<ForestWindAudio>();audio.wind=world.wind;audio.forestRoot=go.transform;
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return new{success=true,trees=palette.trees.Length,rocks=palette.rocks.Length,sizeMetres=10000,streamingTileMetres=ExplorationWorld.TileSize};
 }
}


